 1→"use client";
 2→
 3→import { useInView } from "@/lib/hooks";
 4→import { T } from "@/lib/tokens";
 5→
 6→interface AnimatedTextProps {
 7→  text: string;
 8→  as?: "p" | "h1" | "h2" | "h3" | "span" | "div";
 9→  style?: React.CSSProperties;
10→  delay?: number;
11→}
12→
13→export function AnimatedText({ text, as: Tag = "p", style = {}, delay = 0 }: AnimatedTextProps) {
14→  const [ref, inView] = useInView({ threshold: 0.3 });
15→
16→  const words = text.split(" ");
17→  const lineSize = Math.ceil(words.length / 2);
18→  const lines = [
19→    words.slice(0, lineSize).join(" "),
20→    words.slice(lineSize).join(" "),
21→  ].filter((l) => l.length > 0);
22→
23→  return (
24→    <div ref={ref}>
25→    <Tag style={{ ...style, overflow: "hidden" }}>
26→      {lines.map((line, i) => (
27→        <span
28→          key={i}
29→          style={{
30→            display: "block",
31→            opacity: inView ? 1 : 0,
32→            transform: inView ? "translateY(0)" : "translateY(-100%)",
33→            transition: `all 700ms ${T.easeOut} ${delay + i * 120}ms`,
34→          }}
35→        >
36→          {line}{" "}
37→        </span>
38→      ))}
39→    </Tag>
40→    </div>
41→  );
42→}
