 1→"use client";
 2→
 3→import { useMemo } from "react";
 4→import { GridCard } from "./GridCard";
 5→import { PROJECTS } from "@/lib/projects";
 6→import type { GridRow, GridRowType } from "@/lib/types";
 7→import styles from "./EditorialGrid.module.css";
 8→
 9→function colsFor(type: GridRowType): string {
10→  switch (type) {
11→    case "wide-narrow":
12→      return "2fr 1fr";
13→    case "narrow-wide":
14→      return "1fr 2fr";
15→    case "triple":
16→      return "1fr 1fr 1fr";
17→    default:
18→      return "1fr";
19→  }
20→}
21→
22→function responsiveClass(type: GridRowType): string {
23→  if (type === "triple") return "grid-triple";
24→  if (type === "wide-narrow" || type === "narrow-wide") return "grid-pair";
25→  return "";
26→}
27→
28→interface EditorialGridProps {
29→  rows: GridRow[];
30→  filterCategory?: string;
31→}
32→
33→export function EditorialGrid({ rows, filterCategory = "All" }: EditorialGridProps) {
34→  const filteredRows = useMemo(() => {
35→    if (filterCategory === "All") return rows;
36→    return rows
37→      .map((row) => {
38→        const filtered = row.slugs
39→          .map((slug, i) => {
40→            const p = PROJECTS.find((pr) => pr.slug === slug);
41→            return p && p.category === filterCategory ? i : -1;
42→          })
43→          .filter((i) => i !== -1);
44→
45→        if (filtered.length === 0) return null;
46→
47→        return {
48→          ...row,
49→          type:
50→            filtered.length === 1
51→              ? ("hero" as GridRowType)
52→              : filtered.length === 2 && row.type === "triple"
53→                ? ("wide-narrow" as GridRowType)
54→                : row.type,
55→          slugs: filtered.map((i) => row.slugs[i]),
56→          text: filtered.map((i) => row.text[i]),
57→          heights: filtered.map((i) => row.heights[i]),
58→        };
59→      })
60→      .filter((row): row is GridRow => row !== null);
61→  }, [rows, filterCategory]);
62→
63→  return (
64→    <div className={styles.container}>
65→      {filteredRows.map((row, ri) => (
66→        <div
67→          key={ri}
68→          className={`${styles.row} ${responsiveClass(row.type)}`}
69→          style={{ gridTemplateColumns: colsFor(row.type) }}
70→        >
71→          {row.slugs.map((slug, si) => {
72→            const project = PROJECTS.find((p) => p.slug === slug);
73→            if (!project) return null;
74→            return (
75→              <GridCard
76→                key={slug}
77→                project={project}
78→                showText={row.text[si]}
79→                height={row.heights[si]}
80→              />
81→            );
82→          })}
83→        </div>
84→      ))}
85→    </div>
86→  );
87→}
