 1→"use client";
 2→
 3→import { useState, useEffect, useRef, type RefObject } from "react";
 4→
 5→interface UseInViewOptions {
 6→  threshold?: number;
 7→  rootMargin?: string;
 8→}
 9→
10→export function useInView(options: UseInViewOptions = {}): [RefObject<HTMLDivElement | null>, boolean] {
11→  const ref = useRef<HTMLDivElement | null>(null);
12→  const [inView, setInView] = useState(false);
13→
14→  useEffect(() => {
15→    const el = ref.current;
16→    if (!el) return;
17→    const observer = new IntersectionObserver(
18→      ([entry]) => {
19→        if (entry.isIntersecting) {
20→          setInView(true);
21→          observer.unobserve(el);
22→        }
23→      },
24→      {
25→        threshold: options.threshold ?? 0.15,
26→        rootMargin: options.rootMargin ?? "0px 0px -10% 0px",
27→      }
28→    );
29→    observer.observe(el);
30→    return () => observer.disconnect();
31→  }, [options.threshold, options.rootMargin]);
32→
33→  return [ref, inView];
34→}
35→
36→export function useMouse(ref: RefObject<HTMLElement | null>) {
37→  const [pos, setPos] = useState({ x: 0.5, y: 0.5 });
38→
39→  useEffect(() => {
40→    const el = ref.current;
41→    if (!el) return;
42→    const handler = (e: MouseEvent) => {
43→      const rect = el.getBoundingClientRect();
44→      setPos({
45→        x: (e.clientX - rect.left) / rect.width,
46→        y: (e.clientY - rect.top) / rect.height,
47→      });
48→    };
49→    el.addEventListener("mousemove", handler);
50→    return () => el.removeEventListener("mousemove", handler);
51→  }, [ref]);
52→
53→  return pos;
54→}
55→
56→export function useScrollProgress() {
57→  const [progress, setProgress] = useState(0);
58→
59→  useEffect(() => {
60→    const handler = () => {
61→      const scrollTop = window.scrollY;
62→      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
63→      setProgress(docHeight > 0 ? Math.min(1, Math.max(0, scrollTop / docHeight)) : 0);
64→    };
65→    window.addEventListener("scroll", handler, { passive: true });
66→    return () => window.removeEventListener("scroll", handler);
67→  }, []);
68→
69→  return progress;
70→}
